    // Compute the convex hull using Graham scan
    std::vector<Point2d> hull;
    std::vector<Point2d> sortedPoints = points;
    std::sort(sortedPoints.begin(), sortedPoints.end(), [](const Point2d& a, const Point2d& b) {
        return a.x() < b.x() || (a.x() == b.x() && a.y() < b.y());
    });

    // Graham scan to get the convex hull
    auto cross = [](const Point2d& O, const Point2d& A, const Point2d& B) {
        return (A.x() - O.x()) * (B.y() - O.y()) - (A.y() - O.y()) * (B.x() - O.x());
    };

    size_t n = sortedPoints.size();
    std::vector<Point2d> hullPoints(2 * n);
    size_t k = 0;

    // Build lower hull
    for (size_t i = 0; i < n; ++i) {
        while (k >= 2 && cross(hullPoints[k-2], hullPoints[k-1], sortedPoints[i]) <= 0) {
            k--;
        }
        hullPoints[k++] = sortedPoints[i];
    }

    // Build upper hull
    size_t t = k + 1;
    for (size_t i = n - 1; i > 0; --i) {
        while (k >= t && cross(hullPoints[k-2], hullPoints[k-1], sortedPoints[i-1]) <= 0) {
            k--;
        }
        hullPoints[k++] = sortedPoints[i-1];
    }

    hullPoints.resize(k-1);

    // Now we have the convex hull in hullPoints
    // Find the minimum bounding box using rotating calipers method
    double minArea = std::numeric_limits<double>::max();
    BoundingBox2 minBox;

    // For each edge of the convex hull, we calculate the bounding box when the edge is aligned with x-axis
    for (size_t i = 0; i < hullPoints.size(); ++i) {
        const Point2d& p1 = hullPoints[i];
        const Point2d& p2 = hullPoints[(i + 1) % hullPoints.size()];

        // Edge vector
        double dx = p2.x() - p1.x();
        double dy = p2.y() - p1.y();

        // Angle of the edge with respect to x-axis
        double angle = std::atan2(dy, dx);

        // Create rotation matrix to align this edge with x-axis
        double cosTheta = std::cos(-angle);
        double sinTheta = std::sin(-angle);

        // Rotate all points
        std::vector<Point2d> rotatedPoints;
        for (const Point2d& p : points) {
            double x = p.x() * cosTheta - p.y() * sinTheta;
            double y = p.x() * sinTheta + p.y() * cosTheta;
            rotatedPoints.emplace_back(x, y);
        }

        // Find min and max coordinates of rotated points
        double minX = std::numeric_limits<double>::max();
        double minY = std::numeric_limits<double>::max();
        double maxX = -std::numeric_limits<double>::max();
        double maxY = -std::numeric_limits<double>::max();

        for (const Point2d& p : rotatedPoints) {
            if (p.x() < minX) minX = p.x();
            if (p.y() < minY) minY = p.y();
            if (p.x() > maxX) maxX = p.x();
            if (p.y() > maxY) maxY = p.y();
        }

        // Calculate area of the bounding box
        double area = (maxX - minX) * (maxY - minY);
        if (area < minArea) {
            minArea = area;
            minBox.setMin(Point2d(minX, minY));
            minBox.setMax(Point2d(maxX, maxY));
        }
    }

    return minBox;

